        const hard=[["Ag","NO3"],["Pb","SO4"],["Ag","SO4"],["NH4","PO4"],["NH4","S"],["K","OH"],["Ba","OH"],["Ca","OH"],["Hg2","Br"],["Ca","SO4"],["Sr","SO4"],["Zn","S"],["Pb","NO3"],["Mg","SO4"],["Cu","SO4"],["Hg2","SO4"],["Na","CO3"],["Bi","Cl"],["Sr","OH"],["Ni","CO3"]];
