/* ===== data/examples/m3.js ===== */
/* Module 3 course-notes examples: one parallel problem for each numbered example (3-1 to 3-4) and for the unnumbered
   example questions (Hund's rule p. 4, Cr and Cu p. 7, Mg ionization p. 11, the IE dips pp. 12-13, the EA equations p. 14).
   Same skill, new species or numbers. Values not printed in the notes are given in the question and labelled. */
C120.addExamples([
  {id:"CN3-1", src:"Parallel to Example 3-1", lec:"M3C2", page:"p. 5",
    q:"What is the ground-state electron configuration of a Kr atom? Of a Co atom? How many unpaired electrons does each have?",
    sol:["Kr has 36 electrons. Fill in $n + l$ order: $1s^2\\,2s^2\\,2p^6\\,3s^2\\,3p^6\\,4s^2\\,3d^{10}\\,4p^6$ (2 + 2 + 6 + 2 + 6 + 2 + 10 + 6 = 36).","Every subshell of Kr is full, so it has 0 unpaired electrons.","Co has 27 electrons: $1s^2\\,2s^2\\,2p^6\\,3s^2\\,3p^6$ uses 18, $4s^2$ brings it to 20, and $3d^7$ uses the last 7.","$3d^7$ in five orbitals by Hund's rule: ↑↓ ↑↓ ↑ ↑ ↑, so 3 unpaired electrons."],
    ans:"Kr: $1s^2\\,2s^2\\,2p^6\\,3s^2\\,3p^6\\,4s^2\\,3d^{10}\\,4p^6$, 0 unpaired. Co: $1s^2\\,2s^2\\,2p^6\\,3s^2\\,3p^6\\,4s^2\\,3d^7$, 3 unpaired."},
  {id:"CN3-p4", src:"Parallel to the Hund's rule questions", lec:"M3C2", page:"p. 4",
    q:"Three electrons go into the three degenerate $2p$ orbitals of a nitrogen atom. Compare (A) ↑↓ &nbsp; ↑ &nbsp; _, (B) ↑ &nbsp; ↑ &nbsp; ↑ and (C) ↑ &nbsp; ↓ &nbsp; ↑. Which is lowest in energy? In that arrangement, does it matter whether all three spins point up or all point down?",
    sol:["Hund's rule: with degenerate orbitals only partly filled, the lowest energy arrangement has the most parallel spins (p. 4).","(A) pairs two electrons while an orbital is empty: only one unpaired spin.","(C) uses three orbitals, but the spins are not all parallel.","(B) has three electrons in separate orbitals with parallel spins: the most parallel spins possible, so it is lowest. Parallel spins avoid each other more, shield each other less and feel more pull from the nucleus.","All up or all down: no direction is special, so the two have the same energy."],
    ans:"(B) is the ground state. All up and all down are equivalent."},
  {id:"CN3-2", src:"Parallel to Example 3-2", lec:"M3C3", page:"p. 7",
    q:"Use the periodic table to write the abbreviated ground-state configurations of Se and Sc. How many unpaired electrons does each atom have?",
    sol:["Both are in period 4, so the core is $[\\mathrm{Ar}]$ (18 electrons).","Se is in group 16 of the p block. Walking across period 4: $4s^2$, then $3d^{10}$, then $4p^{G-12} = 4p^4$. Se $= [\\mathrm{Ar}]\\,4s^2\\,3d^{10}\\,4p^4$. Check: $18 + 2 + 10 + 4 = 34$.","$4p^4$ in three orbitals: ↑↓ ↑ ↑, so 2 unpaired.","Sc is in group 3 of the d block: $4s^2\\,3d^{G-2} = 4s^2\\,3d^1$. Sc $= [\\mathrm{Ar}]\\,4s^2\\,3d^1$. Check: $18 + 3 = 21$.","One $3d$ electron: 1 unpaired."],
    ans:"Se $= [\\mathrm{Ar}]\\,4s^2\\,3d^{10}\\,4p^4$ (2 unpaired); Sc $= [\\mathrm{Ar}]\\,4s^2\\,3d^1$ (1 unpaired)."},
  {id:"CN3-p7", src:"Parallel to the Cr and Cu example", lec:"M3C3", page:"p. 7",
    q:"Molybdenum sits below Cr and silver sits below Cu. Based on their positions, what configurations would you expect for Mo and Ag? The notes star both as exceptions (p. 6). Their measured ground states are $[\\mathrm{Kr}]\\,5s^1\\,4d^5$ and $[\\mathrm{Kr}]\\,5s^1\\,4d^{10}$ (given here; you are not expected to know them).",
    sol:["Mo: period 5, group 6, d block. Position gives $[\\mathrm{Kr}]\\,5s^2\\,4d^{G-2} = [\\mathrm{Kr}]\\,5s^2\\,4d^4$ (36 + 6 = 42).","Ag: period 5, group 11. Position gives $[\\mathrm{Kr}]\\,5s^2\\,4d^9$ (36 + 11 = 47).","Experiment: Mo $= [\\mathrm{Kr}]\\,5s^1\\,4d^5$ and Ag $= [\\mathrm{Kr}]\\,5s^1\\,4d^{10}$: the same pattern as Cr and Cu, one $s$ electron found in $d$.","As the notes stress, the pattern does not hold for the whole group: W, below Mo, is $[\\mathrm{Xe}]\\,6s^2\\,4f^{14}\\,5d^4$. So the Aufbau procedure is not always right, and the \"half-filled stability\" explanation does not work. For tests, know only Cr and Cu."],
    ans:"Expected: Mo $[\\mathrm{Kr}]\\,5s^2\\,4d^4$, Ag $[\\mathrm{Kr}]\\,5s^2\\,4d^9$. Measured: $[\\mathrm{Kr}]\\,5s^1\\,4d^5$ and $[\\mathrm{Kr}]\\,5s^1\\,4d^{10}$."},
  {id:"CN3-3", src:"Parallel to Example 3-3", lec:"M3C4", page:"p. 8",
    q:"What is the ground-state electron configuration of each ion? (a) $\\ce{N-}$ (b) $\\ce{Se+}$ (c) $\\ce{Co^2+}$",
    sol:["(a) N is $[\\mathrm{He}]\\,2s^2\\,2p^3$. An anion adds electrons in the $n + l$ order, so the extra electron goes into $2p$: $\\ce{N-} = [\\mathrm{He}]\\,2s^2\\,2p^4$.","(b) Se is $[\\mathrm{Ar}]\\,4s^2\\,3d^{10}\\,4p^4$. A cation loses from the highest $n$ ($n = 4$: $4s$ and $4p$), and of those from the highest $l$ ($4p$): $\\ce{Se+} = [\\mathrm{Ar}]\\,4s^2\\,3d^{10}\\,4p^3$.","(c) Co is $[\\mathrm{Ar}]\\,4s^2\\,3d^7$. The two electrons come from $4s$ (highest $n$): $\\ce{Co^2+} = [\\mathrm{Ar}]\\,3d^7$.","Trap for (c): filling 25 electrons blindly by $n + l$ gives $[\\mathrm{Ar}]\\,4s^2\\,3d^5$, which is neutral Mn, not $\\ce{Co^2+}$."],
    ans:"(a) $[\\mathrm{He}]\\,2s^2\\,2p^4$ (b) $[\\mathrm{Ar}]\\,4s^2\\,3d^{10}\\,4p^3$ (c) $[\\mathrm{Ar}]\\,3d^7$"},
  {id:"CN3-4", src:"Parallel to Example 3-4", lec:"M3C4", page:"p. 9",
    q:"Using the general valence configurations of the periodic table, how many unpaired electrons do ground-state atoms of groups 1, 2, 14, 16 and 18 have? Which of these groups are diamagnetic?",
    sol:["Group 1: $ns^1$, so 1 unpaired: paramagnetic.","Group 2: $ns^2$, all paired: diamagnetic.","Group 14: $ns^2\\,np^2$; the two $p$ electrons sit in separate orbitals (Hund), so 2 unpaired: paramagnetic.","Group 16: $ns^2\\,np^4$: ↑↓ ↑ ↑, so 2 unpaired: paramagnetic.","Group 18: $ns^2\\,np^6$ (He: $1s^2$), all paired: diamagnetic.","An atom is diamagnetic only when every electron is paired (p. 9)."],
    ans:"Unpaired: group 1: 1, group 2: 0, group 14: 2, group 16: 2, group 18: 0. Diamagnetic: groups 2 and 18."},
  {id:"CN3-p11", src:"Parallel to the magnesium ionization energies", lec:"M3C5", page:"p. 11",
    q:"For calcium, $IE(1) = 590$ kJ mol⁻¹ and $IE(2) = 1145$ kJ mol⁻¹ (standard values, not from the notes). Write the two ionization equations and find $\\Delta H$ for $\\ce{Ca(g) -> Ca^2+(g) + 2e-}$. Why is $IE(2)$ larger than $IE(1)$?",
    sol:["$\\ce{Ca(g) -> Ca+(g) + e-}$, $\\Delta H = IE(1) = 590$ kJ mol⁻¹.","$\\ce{Ca+(g) -> Ca^2+(g) + e-}$, $\\Delta H = IE(2) = 1145$ kJ mol⁻¹.","Add the two steps: $\\ce{Ca(g) -> Ca^2+(g) + 2e-}$, $\\Delta H = 590 + 1145 = 1735$ kJ mol⁻¹.","The second electron is pulled away from an ion that is already positive, so it is held more tightly: $IE(1) < IE(2)$ (p. 11)."],
    ans:"$\\Delta H = 1735$ kJ mol⁻¹. $IE(2) > IE(1)$ because the second electron leaves a positive ion."},
  {id:"CN3-p12", src:"Parallel to \"Why does IE decrease from Be to B and from N to O?\"", lec:"M3C5", page:"pp. 12-13",
    q:"Explain why the first ionization energy drops from Mg to Al, and from P to S.",
    sol:["Mg is $[\\mathrm{Ne}]\\,3s^2$ and Al is $[\\mathrm{Ne}]\\,3s^2\\,3p^1$. Al's electron comes out of $3p$, a higher-energy orbital than Mg's $3s$, so it is easier to remove (the same reason as Be to B).","P is $[\\mathrm{Ne}]\\,3s^2\\,3p^3$ with three unpaired $3p$ electrons. S is $[\\mathrm{Ne}]\\,3s^2\\,3p^4$: ionizing S removes one of a pair.","Paired electrons are closer together on average and repel more, so one is easier to remove. Seen the other way, P's unpaired, parallel-spin electrons shield each other less and feel a larger effective nuclear charge, so they are harder to remove.","As for N to O, the notes do not pick one picture. What matters: the drop comes once the $p$ orbitals start to be shared."],
    ans:"Mg to Al: the electron leaves a higher-energy $3p$ orbital. P to S: S loses a paired $3p$ electron; the drop starts when $p$ orbitals are shared."},
  {id:"CN3-p14", src:"Parallel to the electron affinities of C, O and F", lec:"M3C6", page:"p. 14",
    q:"Using the notes' table, write the equations and values for the first electron affinities of S and Cl. Then write the equation for the second electron affinity of S and predict its sign.",
    sol:["$\\ce{S(g) + e- -> S-(g)}$: $EA(1) = -200$ kJ mol⁻¹ (energy released).","$\\ce{Cl(g) + e- -> Cl-(g)}$: $EA(1) = -349$ kJ mol⁻¹, the most negative value in the table.","$\\ce{S-(g) + e- -> S^2-(g)}$ is the second electron affinity of S.","The electron is pushed onto an ion that is already negative, so energy must be supplied: positive, just like $EA(2) = +744$ kJ mol⁻¹ for O. (The notes do not give a value for S.)"],
    ans:"S: $-200$; Cl: $-349$ kJ mol⁻¹. $\\ce{S-(g) + e- -> S^2-(g)}$ has a positive EA."}
]);


